<script setup>
import { computed,onMounted,ref } from 'vue'; import api from '../../services/api'; import {useAuthStore} from '../../stores/auth'; import FormErrors from '../../components/ui/FormErrors.vue';
const auth=useAuthStore();const data=ref({stats:{},expiring_trials:[],recent_activity:[]});const loading=ref(true);const error=ref(null);
const cards=computed(()=>[['Total Clinics',data.value.stats.total_clinics||0,'mint'],['Active Clinics',data.value.stats.active_clinics||0,'blue'],['Trial Clinics',data.value.stats.trial_clinics||0,'amber'],['Suspended Clinics',data.value.stats.suspended_clinics||0,'rose'],['Active Members',data.value.stats.total_members||0,'violet']]);
const format=v=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(v));
onMounted(async()=>{try{data.value=(await api.get('/v1/platform/dashboard')).data.data}catch(e){error.value=e}finally{loading.value=false}});
</script><template><div><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>Welcome back, {{auth.user?.name}}!</h1><p>Here is what is happening across your platform.</p></div><time>{{format(new Date())}}</time></header><FormErrors :error="error"/><p v-if="loading" class="loading-state">Loading dashboard…</p><template v-else><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article v-for="[label,value,tone] in cards" :key="label" :class="['stat-card','stat-'+tone]"><div><p class="text-sm text-slate-600">{{label}}</p><p class="mt-1 text-3xl font-bold">{{value}}</p></div></article></div><div class="mt-6 grid gap-6 xl:grid-cols-5"><section class="admin-card xl:col-span-2"><div class="card-heading"><h2>Recent activity</h2><RouterLink :to="{name:'admin.audit'}">View all</RouterLink></div><div v-for="item in data.recent_activity" :key="item.id" class="flex gap-3 border-b py-4"><span class="activity-icon">↻</span><div><p class="font-semibold">{{item.action}}</p><p class="text-sm text-slate-500">{{item.actor_name||'System'}}</p></div></div><p v-if="!data.recent_activity.length" class="empty-state">No recent activity.</p></section><section class="admin-card xl:col-span-3"><div class="card-heading"><h2>Trials expiring soon</h2></div><div class="table-wrap"><table><thead><tr><th>Clinic</th><th>Plan</th><th>Ends</th></tr></thead><tbody><tr v-for="trial in data.expiring_trials" :key="trial.id"><td class="font-semibold">{{trial.name}}</td><td>{{trial.plan_name}}</td><td>{{format(trial.trial_ends_at)}}</td></tr></tbody></table><p v-if="!data.expiring_trials.length" class="empty-state">No trials expire within 14 days.</p></div></section></div></template></div></template>
